interface BundleOverrides {
  certDer?: string;
  signature?: string;
  digest?: string | null;
  integratedTime?: number | null;
}

/** A Sigstore v0.3 bundle over PAYLOAD, with any part swappable for a negative case. */
export function bundle(overrides: BundleOverrides = {}): unknown {
  const digest =
    overrides.digest === undefined ? PAYLOAD_DIGEST_B64 : overrides.digest;
  const time =
    overrides.integratedTime === undefined
      ? INTEGRATED_TIME
      : overrides.integratedTime;
  return {
    mediaType: "application/vnd.dev.sigstore.bundle.v0.3+json",
    verificationMaterial: {
      certificate: { rawBytes: overrides.certDer ?? LEAF_DER },
      ...(time === null
        ? {}
        : { tlogEntries: [{ integratedTime: String(time) }] }),
    },
    messageSignature: {
      ...(digest === null
        ? {}
        : { messageDigest: { algorithm: "SHA2_256", digest } }),
      signature: overrides.signature ?? SIGNATURE,
    },
  };
}

