/**
 * The test leaf's private key, so a suite can sign an arbitrary manifest and get a
 * record the real verifier accepts.
 *
 * Safe to commit: it is a throwaway key under a throwaway root that only
 * `TEST_ROOT_PEM` trusts. The binary pins Fulcio's real roots
 * (`sigstore-roots.ts`), so a record signed with this key is refused everywhere
 * outside a test that pins the test root.
 *
 * It keeps `update.test.ts` running the real verifier; a stubbed verification
 * would let the fail-closed behaviour rot without a test going red.
 */
const TEST_SIGNING_KEY_PKCS8 =
  "MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgV6rI/dk6Mbmqs6NfcV9pr4g2KcehjPsJtkOxx8Jx/+uhRANCAAQhHd0hxm0bizQggKMTbIm4dmcNDd+kDzBPwwaLeJ+ziKHKVyUxQqEEzOBuQ2J0HEs+8z6Ty4RRiwuAhjLgNts9";

const TEST_LEAF_DER =
  "";

/** Signs `manifest` as the release workflow would and returns the Sigstore bundle. */
export async function signManifest(
  manifest: string | Uint8Array,
): Promise<unknown> {
  const bytes = (
    typeof manifest === "string" ? new TextEncoder().encode(manifest) : manifest
  ) as Uint8Array<ArrayBuffer>;
  const key = await crypto.subtle.importKey(
    "pkcs8",
    Uint8Array.from(
      atob(TEST_SIGNING_KEY_PKCS8),
      (ch) => ch.codePointAt(0) ?? 0,
    ),
    { name: "ECDSA", namedCurve: "P-256" },
    false,
    ["sign"],
  );
  // WebCrypto signs to raw r|s; cosign records the DER encoding, so re-encode.
  const raw = new Uint8Array(
    await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, bytes),
  );
  const der = rawEcdsaToDer(raw);
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
  return {
    mediaType: "application/vnd.dev.sigstore.bundle.v0.3+json",
    verificationMaterial: {
      certificate: { rawBytes: TEST_LEAF_DER },
      tlogEntries: [{ integratedTime: String(INTEGRATED_TIME) }],
    },
    messageSignature: {
      messageDigest: { algorithm: "SHA2_256", digest: toBase64(digest) },
      signature: toBase64(der),
    },
  };
}

function toBase64(bytes: Uint8Array): string {
  let out = "";
  for (const byte of bytes) out += String.fromCodePoint(byte);
  return btoa(out);
}

/** raw r|s (32+32) -> `SEQUENCE { INTEGER r, INTEGER s }`. */
function rawEcdsaToDer(raw: Uint8Array): Uint8Array {
  const half = raw.length / 2;
  const ints: number[][] = [];
  for (const part of [raw.subarray(0, half), raw.subarray(half)]) {
    let i = 0;
    while (i < part.length - 1 && part[i] === 0) i++;
    const body = Array.from(part.subarray(i));
    // DER INTEGERs are signed, so a leading high bit needs a zero pad.
    if (body[0] >= 0x80) body.unshift(0);
    ints.push([0x02, body.length, ...body]);
  }
  const content = [...ints[0], ...ints[1]];
  return new Uint8Array([0x30, content.length, ...content]);
}
